55	// What MHPCO insures each item for, as distinct from what it charges to do so.
56	const INSURANCE_VALUES: Record<string, number> = {
57	  sword: 1000,
58	  amulet: 600,
59	  staff: 800,
60	  potion: 400,
61	  rune: 250,
62	  moonstone: 250,
63	};
64	
65	const BASE_PREMIUMS: Record<string, number> = {
66	  sword: 100,
67	  amulet: 60,
68	  staff: 80,
69	  potion: 40,
70	  rune: 25,
71	  moonstone: 25,
72	};
73	
74	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
75	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
76	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
77	// (100 * 110) / 100 is exact.
78	const ONE_HUNDRED_PERCENT = 100;
79	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
80	const ADMIN_FEE = 5;
81	const LOYALTY_YEARS = 2;
82	const LOYALTY_DISCOUNT_PERCENT = 20;
83	const SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT = 15;
84	const DEDUCTIBLE = 100;
85	const CAP_MULTIPLE = 2;
86	
87	const applyPercent = (amount: number, percent: number): number =>
88	  (amount * percent) / ONE_HUNDRED_PERCENT;
89	
90	const addSurcharge = (amount: number, surchargePercent: number): number =>
91	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
92	
93	const applyDiscount = (amount: number, discountPercent: number): number =>
94	  applyPercent(amount, ONE_HUNDRED_PERCENT - discountPercent);
95	
96	const COMPONENT_TYPES = ["rune", "moonstone"];
97	const BUILDING_BLOCK_SIZE = 3;
98	const BUILDING_BLOCK_BASE_PREMIUM = 60;
99	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
100	
101	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
102	
103	// Risk surcharges are per-item properties of the insured object, each raising
104	// that item's premium by a percentage. They stack multiplicatively: an item
105	// matching two rules is surcharged by the first, then by the second.
106	interface RiskSurcharge {
107	  appliesTo: (item: Item) => boolean;
108	  percent: number;
109	}
110	
111	const RISK_SURCHARGES: RiskSurcharge[] = [
112	  { appliesTo: (item) => item.cursed === true, percent: 50 },
113	  { appliesTo: (item) => (item.enchantment ?? 0) >= 5, percent: 30 },
114	];
115	
116	const riskAdjustedPremiumOf = (item: Item): number =>
117	  RISK_SURCHARGES.reduce(
118	    (premium, surcharge) =>
119	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
120	    basePremiumOf(item),
121	  );
122	
123	const sumRiskAdjustedPremiums = (items: Item[]): number =>
124	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
125	
126	// Alike components are grouped into building blocks of 3, which carry a
127	// special base premium; the remaining components are priced individually,
128	// risk surcharges and all.
129	// Total over the empty group: no components means no blocks and no remainder.
130	const alikeComponentsPremium = (components: Item[]): number => {
131	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
132	  const remainingComponents = components.slice(blockCount * BUILDING_BLOCK_SIZE);
133	  return (
134	    blockCount * BUILDING_BLOCK_BASE_PREMIUM +
135	    sumRiskAdjustedPremiums(remainingComponents)
136	  );
137	};
138	
139	// Splits items into those matching the predicate and those not, in one pass,
140	// so the rule dividing them is written exactly once.
141	const partition = (
142	  items: Item[],
143	  matches: (item: Item) => boolean,
144	): [Item[], Item[]] =>
145	  items.reduce<[Item[], Item[]]>(
146	    ([matching, rest], item) =>
147	      matches(item) ? [[...matching, item], rest] : [matching, [...rest, item]],
148	    [[], []],
149	  );
150	
151	const groupByType = (items: Item[]): Item[][] => [
152	  ...items
153	    .reduce(
154	      (groups, item) =>
155	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
156	      new Map<string, Item[]>(),
157	    )
158	    .values(),
159	];
160	
161	// Components and main items are priced by different rules, so each group is
162	// totalled separately: components by building block, main items item by item.
163	const componentsPremium = (components: Item[]): number =>
164	  groupByType(components).reduce(
165	    (total, alike) => total + alikeComponentsPremium(alike),
166	    0,
167	  );
168	
169	// The sum insured is what the items alone are worth to MHPCO, before any
170	// modifier that depends on the customer or the contract they sit in. Every
171	// item is either a component or a main item — the split is stated once, as a
172	// partition, so the two halves cannot drift apart — and each half is priced by
173	// its own rules.
174	const sumInsuredOf = (items: Item[]): number => {
175	  const [components, mainItems] = partition(items, isComponent);
176	  return sumRiskAdjustedPremiums(mainItems) + componentsPremium(components);
177	};
178	
179	// Contract-level modifiers adjust the sum insured by the terms of the deal
180	// rather than the nature of the items. Like risk surcharges they stack
181	// multiplicatively, each applying to the result of the one before, so they are
182	// written the same way: a predicate over the contract, and an adjustment.
183	interface Contract {
184	  customer: Customer;
185	  isFirstContract: boolean;
186	}
187	
188	interface ContractModifier {
189	  appliesTo: (contract: Contract) => boolean;
190	  adjust: (amount: number) => number;
191	}
192	
193	// Every contract is priced on one of two standings: a first insurance is
194	// assessed a surcharge, a later one rewarded with a discount. This is a choice,
195	// not two independent rules, so it is written as one — there is no way to
196	// express a contract that gets both or neither.
197	const standingAdjustedPremiumOf = (
198	  amount: number,
199	  { isFirstContract }: Contract,
200	): number =>
201	  isFirstContract
202	    ? addSurcharge(amount, FIRST_INSURANCE_SURCHARGE_PERCENT)
203	    : applyDiscount(amount, SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT);
204	
205	// Modifiers that a contract may or may not earn, on top of its standing. They
206	// stack multiplicatively, each applying to the result of the one before.
207	const CONTRACT_MODIFIERS: ContractModifier[] = [
208	  {
209	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
210	    adjust: (amount) => applyDiscount(amount, LOYALTY_DISCOUNT_PERCENT),
211	  },
212	];
213	
214	const contractAdjustedPremiumOf = (
215	  sumInsured: number,
216	  contract: Contract,
217	): number =>
218	  CONTRACT_MODIFIERS.reduce(
219	    (premium, modifier) =>
220	      modifier.appliesTo(contract) ? modifier.adjust(premium) : premium,
221	    standingAdjustedPremiumOf(sumInsured, contract),
222	  );
223	
224	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
225	// so that no percentage ever applies to it.
226	const billedPremiumOf = (premium: number): number =>
227	  Math.ceil(premium) + ADMIN_FEE;
228	
229	const quote = (step: QuoteStep, contract: Contract): QuoteResult => ({
230	  premium: billedPremiumOf(
231	    contractAdjustedPremiumOf(sumInsuredOf(step.items), contract),
232	  ),
233	});
234	
235	// The insurance sum is what the items are covered for, and it is the basis of
236	// the payout cap — unrelated to the premium charged for that cover.
237	const insuranceSumOf = (items: Item[]): number =>
238	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
239	
240	// A quote creates a policy, which then absorbs claims: every payout draws down
241	// a cap of twice the insurance sum, so the policy carries state between steps.
242	interface Policy {
243	  remainingCap: number;
244	}
245	
246	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
247	  const damageTotal = step.incident.damages.reduce(
248	    (total, damage) => total + damage.amount,
249	    0,
250	  );
251	  const payout = damageTotal - DEDUCTIBLE;
252	  return { payout, remainingCap: policy.remainingCap - payout };
253	};
254	
255	export const runScenario = (scenario: Scenario): ScenarioResult => {
256	  const policies = new Map<number, Policy>();
257	  const results = scenario.steps.map((step, index) => {
258	    if (step.op === "claim") {
259	      const policy = policies.get(step.policy) as Policy;
260	      const result = claim(step, policy);
261	      policy.remainingCap = result.remainingCap;
262	      return result;
263	    }
264	    policies.set(index, {
265	      remainingCap: insuranceSumOf(step.items) * CAP_MULTIPLE,
266	    });
267	    return quote(step, {
268	      customer: scenario.customer,
269	      isFirstContract: index === 0,
270	    });
271	  });
272	  return { results };
273	};
